// server.js
import express from 'express';
import http from 'http';
import { Server } from 'socket.io';
import mediasoup from 'mediasoup';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: 'http://localhost:5173',
    methods: ['GET', 'POST'],
    credentials: true,
  },
});

app.use('/mediasoup', express.static(path.join(__dirname, 'public')));

const PORT = process.env.PORT || 3000;

let worker;
let router;
const peers = new Map();

const mediaCodecs = [
  {
    kind: 'audio',
    mimeType: 'audio/opus',
    clockRate: 48000,
    channels: 2,
  },
  {
    kind: 'video',
    mimeType: 'video/VP8',
    clockRate: 90000,
    parameters: {
         'x-google-start-bitrate': 1000,
      'x-google-min-bitrate': 500,
      'x-google-max-bitrate': 2000,
    },
  },
];

const createWorker = async () => {
  try {
    worker = await mediasoup.createWorker();
    router = await worker.createRouter({ mediaCodecs });
    console.log('✅ Mediasoup worker and router created');
    
    // Start listening for Socket.io connections *after* mediasoup is ready
    setupSocketListeners();
  
  } catch (err) {
    console.error('❌ Error creating worker/router:', err);
    process.exit(1); // Exit if critical setup fails
  }
};

const setupSocketListeners = () => {
  io.of('/mediasoup').on('connection', socket => {
    console.log(`🔌 Client connected: ${socket.id}`);
    socket.emit('connection-success', { socketId: socket.id });

    peers.set(socket.id, {
      transports: [],
      producers: [],
      consumers: [],
      peerDetails: {},
    });

    socket.on('joinRoom', async ({ roomName }, callback) => {
      console.log(`🚪 ${socket.id} joined room: ${roomName}`);
      // The router object is guaranteed to be available here
      callback({ rtpCapabilities: router.rtpCapabilities });
    });

    socket.on('createWebRtcTransport', async ({ consumer }, callback) => {
      try {
        console.log(`🚚 Creating WebRTC transport for ${consumer ? 'consumer' : 'producer'}`);
        const transport = await router.createWebRtcTransport({
          listenIps: [{ ip: '0.0.0.0', announcedIp: null }],
          enableUdp: true,
          enableTcp: true,
          preferUdp: true,
        });

        const peer = peers.get(socket.id);
        if (!peer) {
          console.warn('⚠️ Peer not found');
          return callback({ params: { error: 'Peer not found' } });
        }

        peer.transports.push({
          transport,
          role: consumer ? 'consumer' : 'producer',
          connected: false,
        });

        callback({
          params: {
            id: transport.id,
            iceParameters: transport.iceParameters,
            iceCandidates: transport.iceCandidates,
            dtlsParameters: transport.dtlsParameters,
          },
        });

        transport.observer.on('close', () => {
          console.log('❌ Transport closed');
        });
      } catch (err) {
        console.error('❌ Transport creation error:', err);
        callback({ params: { error: err.message } });
      }
    });

    socket.on('transport-connect', async ({ dtlsParameters }) => {
      try {
        const peer = peers.get(socket.id);
        if (!peer) return;

        const entry = peer.transports.find(t => t.role === 'producer');
        if (!entry || entry.connected) return;

        await entry.transport.connect({ dtlsParameters });
        entry.connected = true;
        console.log('✅ Producer transport connected');
      } catch (err) {
        console.error('❌ Error connecting transport:', err);
      }
    });

    socket.on('transport-produce', async ({ kind, rtpParameters, appData }, callback) => {
      try {
        const peer = peers.get(socket.id);
        if (!peer) return;

        const entry = peer.transports.find(t => t.role === 'producer');
        if (!entry) return;

        const producer = await entry.transport.produce({ kind, rtpParameters, appData });
        peer.producers.push(producer);

        console.log(`📡 Producer created: ${producer.id}`);
        socket.broadcast.emit('new-producer', { producerId: producer.id });

        callback({ id: producer.id, producersExist: true });
      } catch (err) {
        console.error('❌ Error producing media:', err);
        callback({ error: err.message });
      }
    });

    socket.on('getProducers', callback => {
      const producerIds = [];
      for (const [id, peer] of peers.entries()) {
        if (id !== socket.id) {
          peer.producers.forEach(p => producerIds.push(p.id));
        }
      }
      console.log(`📦 Sending producer list:`, producerIds);
      callback(producerIds);
    });

    socket.on('transport-recv-connect', async ({ dtlsParameters, serverConsumerTransportId }) => {
      try {
        const peer = peers.get(socket.id);
        if (!peer) return;

        const entry = peer.transports.find(t => t.transport.id === serverConsumerTransportId);
        if (!entry || entry.connected) return;

        await entry.transport.connect({ dtlsParameters });
        entry.connected = true;
        console.log('✅ Consumer transport connected');
      } catch (err) {
        console.error('❌ Error connecting consumer transport:', err);
      }
    });

    socket.on('consume', async ({ rtpCapabilities, remoteProducerId, serverConsumerTransportId }, callback) => {
      try {
        if (!router.canConsume({ producerId: remoteProducerId, rtpCapabilities })) {
          throw new Error('Cannot consume');
        }

        const peer = peers.get(socket.id);
        if (!peer) return;

        const entry = peer.transports.find(t => t.transport.id === serverConsumerTransportId);
        if (!entry) return callback({ params: { error: 'Transport not found' } });

        const consumer = await entry.transport.consume({
          producerId: remoteProducerId,
          rtpCapabilities,
          paused: true,
        });

        peer.consumers.push(consumer);

        consumer.on('transportclose', () => {
          console.log('❌ Consumer transport closed');
        });

        console.log(`🎥 Consumer created for producer ${remoteProducerId}`);
        callback({
          params: {
            id: consumer.id,
            producerId: remoteProducerId,
            kind: consumer.kind,
            rtpParameters: consumer.rtpParameters,
            serverConsumerId: consumer.id,
          },
        });
      } catch (err) {
        console.error('❌ Error consuming media:', err);
        callback({ params: { error: err.message } });
      }
    });

    socket.on('consumer-resume', async ({ serverConsumerId }) => {
      try {
        const peer = peers.get(socket.id);
        if (!peer) return;

        const consumer = peer.consumers.find(c => c.id === serverConsumerId);
        if (consumer) {
          await consumer.resume();
          console.log(`▶️ Consumer resumed: ${serverConsumerId}`);
        }
      } catch (err) {
        console.error('❌ Error resuming consumer:', err);
      }
    });

    socket.on('disconnect', () => {
      console.log(`🔌 Client disconnected: ${socket.id}`);
      const peer = peers.get(socket.id);
      if (!peer) return;

      peer.transports.forEach(t => t.transport.close());
      peer.producers.forEach(p => p.close());
      peer.consumers.forEach(c => c.close());

      peers.delete(socket.id);
      console.log(`🧹 Cleaned up peer: ${socket.id}`);
    });
  });
};

createWorker();

server.listen(PORT, () => console.log(`✅ Server running on port ${PORT}`));